-- Apply after 202610310001_admin_and_blog.sql. Existing settings and packages are preserved.
create table if not exists public.pricing_packages (
 slug text primary key check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 3 and 100),
 name text not null check(char_length(name) between 3 and 100),
 category text not null check(char_length(category) between 3 and 80),
 description text not null check(char_length(description) between 20 and 800),
 currency text not null check(currency in ('USD','KES','EUR','GBP')),
 price_min integer not null check(price_min between 0 and 100000000),
 price_max integer not null check(price_max between price_min and 100000000),
 billing text not null check(billing in ('project','engagement','month')),
 timeline text not null check(char_length(timeline) between 3 and 140),
 features jsonb not null check(jsonb_typeof(features)='array' and jsonb_array_length(features) between 1 and 30),
 exclusions jsonb not null check(jsonb_typeof(exclusions)='array' and jsonb_array_length(exclusions) between 1 and 20),
 published boolean not null default false,
 sort_order integer not null default 100 check(sort_order between 0 and 10000)
);
alter table public.pricing_packages enable row level security;
revoke all on public.pricing_packages from anon,authenticated;
grant select on public.pricing_packages to anon,authenticated;
grant insert,update,delete on public.pricing_packages to authenticated;
drop policy if exists public_read_pricing on public.pricing_packages;
create policy public_read_pricing on public.pricing_packages for select to anon,authenticated using(published=true);
drop policy if exists admin_manage_pricing on public.pricing_packages;
create policy admin_manage_pricing on public.pricing_packages for all to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create table if not exists public.studio_settings (
 id text primary key check(id='main'),
 inquiry_email text not null check(char_length(inquiry_email) between 3 and 254 and inquiry_email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$')
);
alter table public.studio_settings enable row level security;
revoke all on public.studio_settings from anon,authenticated;
grant select on public.studio_settings to authenticated;
grant update(inquiry_email) on public.studio_settings to authenticated;
grant select on public.studio_settings to service_role;
drop policy if exists admin_read_settings on public.studio_settings;
create policy admin_read_settings on public.studio_settings for select to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
drop policy if exists admin_update_settings on public.studio_settings;
create policy admin_update_settings on public.studio_settings for update to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
insert into public.studio_settings(id,inquiry_email) values('main','pjuma655@gmail.com') on conflict do nothing;
